const b = $('Webhook').first().json.body || {};
if (b.evento !== 'rotacion_solicitud_marca' || !Array.isArray(b.para) || b.para.length === 0) return [];
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const usd = (n) => Number(n || 0).toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const filas = (b.productos || []).slice(0, 40).map((p) => '<tr><td style="padding:4px 8px;border:1px solid #ddd">' + esc(p.codigo) + '</td><td style="padding:4px 8px;border:1px solid #ddd">' + esc(p.producto) + '</td><td style="padding:4px 8px;border:1px solid #ddd;text-align:right">' + esc(p.unidades) + '</td><td style="padding:4px 8px;border:1px solid #ddd;text-align:right">' + esc(p.dias_sin_venta) + '</td></tr>').join('');
const mas = (b.productos || []).length > 40 ? '<p>… y ' + ((b.productos.length) - 40) + ' más en el Excel adjunto.</p>' : '';
const html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#111">' + esc(b.mensaje).replace(/\n/g, '<br>') +
  '<table style="border-collapse:collapse;margin-top:16px;font-size:12px"><tr style="background:#1e293b;color:#fff"><th style="padding:4px 8px">Código</th><th style="padding:4px 8px">Producto</th><th style="padding:4px 8px">Unidades</th><th style="padding:4px 8px">Días sin venta</th></tr>' + filas + '</table>' + mas + '</div>';
const adj = b.adjunto || {};
return [{
  json: { to: b.para.join(','), cc: (b.cc || []).join(','), subject: b.asunto, html },
  binary: adj.base64 ? { adjunto: { data: adj.base64, mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: adj.nombre || 'solicitud.xlsx' } } : {},
}];
